// Danh sách thành viên nhóm
const members = [
  {
    id: 1,
    name: 'Lê Trọng Hiếu',
    studentId: 'B23DVCN051',
    tasks: [
      'Xây dựng khung hệ thống, cấu hình route và layout chung.',
      'Phụ trách Header, Sidebar, ProtectedRoute và xử lý localStorage dùng chung.',
      'Tạo thêm trang Giới thiệu nhóm và tổng hợp source code.',
    ],
  },
  {
    id: 2,
    name: 'Bùi Thị Khánh Uyên',
    studentId: 'B23DVCN175',
    tasks: [
      'Xây dựng chức năng đăng nhập.',
      'Xây dựng trang Dashboard thống kê tổng quan.',
      'Hiển thị thông tin tổng quan về nhân viên, phòng ban và đơn nghỉ phép.',
    ],
  },
  {
    id: 3,
    name: 'Nguyễn Tiến Hiếu',
    studentId: 'B23DVCN055',
    tasks: [
      'Xây dựng module Quản lý nhân viên.',
      'Thực hiện chức năng thêm, sửa, xóa, tìm kiếm và lọc nhân viên.',
      'Xây dựng trang xem chi tiết thông tin nhân viên.',
    ],
  },
  {
    id: 4,
    name: 'Phạm Quang Minh',
    studentId: 'B23DVCN107',
    tasks: [
      'Xây dựng module Quản lý phòng ban.',
      'Thực hiện chức năng thêm, sửa, xóa, tìm kiếm và lọc phòng ban.',
      'Xây dựng trang Hồ sơ cá nhân và chức năng cập nhật thông tin người dùng.',
    ],
  },
  {
    id: 5,
    name: 'Phạm Ngọc Minh Hoàng',
    studentId: 'B23DVCN059',
    tasks: [
      'Xây dựng module Chấm công.',
      'Xây dựng module Quản lý nghỉ phép.',
      'Thực hiện chức năng tạo, sửa, xóa, duyệt và từ chối đơn nghỉ phép.',
    ],
  },
];

// Bảng phân công công việc
const assignments = [
  {
    id: 1,
    name: 'Lê Trọng Hiếu',
    studentId: 'B23DVCN051',
    files: 'App.js, index.js, Layout.jsx, Header.jsx, Sidebar.jsx, ProtectedRoute.jsx, storage.js, AboutTeam.jsx',
    content: 'Xây dựng khung hệ thống, điều hướng, layout chung, bảo vệ route, xử lý localStorage và trang giới thiệu nhóm.',
  },
  {
    id: 2,
    name: 'Bùi Thị Khánh Uyên',
    studentId: 'B23DVCN175',
    files: 'Login.jsx, Dashboard.jsx',
    content: 'Xây dựng chức năng đăng nhập và trang dashboard thống kê tổng quan.',
  },
  {
    id: 3,
    name: 'Nguyễn Tiến Hiếu',
    studentId: 'B23DVCN055',
    files: 'Employees.jsx, EmployeeDetail.jsx',
    content: 'Xây dựng module quản lý nhân viên và trang chi tiết nhân viên.',
  },
  {
    id: 4,
    name: 'Phạm Quang Minh',
    studentId: 'B23DVCN107',
    files: 'Departments.jsx, Profile.jsx',
    content: 'Xây dựng module quản lý phòng ban và hồ sơ cá nhân.',
  },
  {
    id: 5,
    name: 'Phạm Ngọc Minh Hoàng',
    studentId: 'B23DVCN059',
    files: 'Attendance.jsx, LeaveRequests.jsx',
    content: 'Xây dựng module chấm công và quản lý nghỉ phép.',
  },
];

function AboutTeam() {
  return (
    <div>
      {/* Tiêu đề trang */}
      <h4 style={{ marginBottom: '4px', color: '#111' }}>Giới thiệu nhóm thực hiện</h4>
      <p style={{ color: '#888', fontSize: '14px', marginBottom: '24px' }}>
        Đây là nhóm sinh viên thực hiện project HRM System - Website quản lý nhân sự công ty.
      </p>

      {/* Thông tin project */}
      <div style={{
        backgroundColor: '#fff',
        border: '1px solid #ddd',
        borderRadius: '8px',
        padding: '20px',
        marginBottom: '24px'
      }}>
        <h6 style={{ marginBottom: '14px', color: '#333' }}>Thông tin project</h6>
        {[
          { label: 'Tên project', value: 'HRM System' },
          { label: 'Chủ đề', value: 'Website quản lý nhân sự công ty' },
          { label: 'Công nghệ sử dụng', value: 'ReactJS, JavaScript, localStorage' },
          { label: 'Hình thức dữ liệu', value: 'Dữ liệu giả lập lưu trên trình duyệt' },
        ].map((row) => (
          <div key={row.label} style={{
            display: 'flex',
            padding: '8px 0',
            borderBottom: '1px solid #f0f0f0',
            fontSize: '14px'
          }}>
            <span style={{ color: '#888', width: '200px', flexShrink: 0 }}>{row.label}</span>
            <span style={{ color: '#222' }}>{row.value}</span>
          </div>
        ))}
      </div>

      {/* Danh sách thành viên */}
      <h6 style={{ marginBottom: '14px', color: '#333' }}>Danh sách thành viên</h6>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginBottom: '28px' }}>
        {members.map((member) => (
          <div
            key={member.id}
            style={{
              backgroundColor: '#fff',
              border: '1px solid #ddd',
              borderRadius: '8px',
              padding: '16px 20px',
            }}
          >
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '10px' }}>
              {/* Avatar chữ số thứ tự */}
              <div style={{
                width: '36px',
                height: '36px',
                borderRadius: '50%',
                backgroundColor: '#2563eb',
                color: '#fff',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontWeight: 'bold',
                fontSize: '14px',
                flexShrink: 0
              }}>
                {member.id}
              </div>
              <div>
                <p style={{ margin: 0, fontWeight: '600', color: '#222', fontSize: '15px' }}>
                  {member.name}
                </p>
                <p style={{ margin: 0, fontSize: '12px', color: '#888' }}>
                  {member.studentId}
                </p>
              </div>
            </div>
            <ul style={{ margin: 0, paddingLeft: '20px' }}>
              {member.tasks.map((task, i) => (
                <li key={i} style={{ fontSize: '13px', color: '#555', marginBottom: '4px' }}>
                  {task}
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>

      {/* Bảng phân công công việc */}
      <h6 style={{ marginBottom: '14px', color: '#333' }}>Phân công công việc</h6>
      <div style={{
        backgroundColor: '#fff',
        border: '1px solid #ddd',
        borderRadius: '8px',
        overflow: 'hidden',
        marginBottom: '16px'
      }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '14px' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8f9fa', borderBottom: '1px solid #ddd' }}>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555', width: '40px' }}>STT</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Thành viên</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Mã sinh viên</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>File phụ trách</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Nội dung công việc</th>
            </tr>
          </thead>
          <tbody>
            {assignments.map((a) => (
              <tr key={a.id} style={{ borderBottom: '1px solid #f0f0f0', verticalAlign: 'top' }}>
                <td style={{ padding: '12px 16px', color: '#888' }}>{a.id}</td>
                <td style={{ padding: '12px 16px', color: '#222', fontWeight: '500' }}>{a.name}</td>
                <td style={{ padding: '12px 16px', color: '#555' }}>{a.studentId}</td>
                <td style={{ padding: '12px 16px', color: '#555', fontSize: '13px' }}>
                  {/* Hiển thị từng file trên một dòng */}
                  {a.files.split(', ').map((f, i) => (
                    <span key={i} style={{ display: 'block' }}>{f}</span>
                  ))}
                </td>
                <td style={{ padding: '12px 16px', color: '#555', fontSize: '13px' }}>{a.content}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default AboutTeam;
